package com.madar.files;
import android.content.Context;
import org.json.*;
import java.io.*;
import java.security.MessageDigest;
import java.nio.charset.StandardCharsets;
import java.util.*;
/** Private declarative projects. No executable code, credentials or arbitrary paths. */
final class MotionProject {
 static String id(){return UUID.randomUUID().toString().replace("-","");}
 static File directory(Context c,String id)throws IOException{if(id==null||!id.matches("[a-f0-9]{32}"))throw new IOException("مشروع غير صالح");File d=new File(new File(c.getFilesDir(),"motion-projects"),id);if(!d.isDirectory()&&!d.mkdirs())throw new IOException("تعذر فتح المشروع");return d;}
 static File asset(Context c,String id,String name)throws IOException{if(!name.matches("asset_[a-f0-9]{32}\\.jpg|voice\\.wav|recording\\.media|speech_[a-f0-9]{64}\\.wav|project\\.json|state\\.json"))throw new IOException("ملف مشروع غير صالح");return new File(directory(c,id),name);}
 static JSONObject load(Context c,String id)throws Exception{JSONObject p=GeminiCheckpoint.read(asset(c,id,"project.json"));if(p==null)throw new IOException("المشروع غير موجود");return validate(p,false);}
 static synchronized void save(Context c,JSONObject p)throws Exception{validate(p,false);GeminiCheckpoint.save(asset(c,p.getString("id"),"project.json"),p);c.getSharedPreferences("motion-studio",0).edit().putString("last",p.getString("id")).apply();}
 static JSONObject create(Context c)throws Exception{JSONObject p=new JSONObject().put("version",1).put("id",id()).put("title","مشروعي الجديد").put("theme","paper").put("aspect","9:16").put("voiceMode","none").put("voice","Charon").put("style","documentary").put("ready",false).put("captions",false).put("scenes",new JSONArray().put(scene("البداية","اكتب هنا أول خطوة أو بداية القصة.")));save(c,p);return p;}
 static JSONObject scene(String title,String text)throws Exception{return new JSONObject().put("id",id().substring(0,12)).put("title",title).put("narration",text).put("seconds",6).put("graphic","steps").put("effect","rise").put("transition","fade").put("image","").put("imageQuery","").put("imageAnchor","").put("credit","").put("illustration",false).put("highlights",new JSONArray()).put("words",new JSONArray());}
 static JSONArray list(Context c)throws Exception{JSONArray out=new JSONArray();File root=new File(c.getFilesDir(),"motion-projects");File[] dirs=root.listFiles();if(dirs==null)return out;Arrays.sort(dirs,Comparator.comparingLong(File::lastModified).reversed());for(File d:dirs)if(d.getName().matches("[a-f0-9]{32}")&&out.length()<50){JSONObject p=GeminiCheckpoint.read(new File(d,"project.json"));if(p!=null)out.put(new JSONObject().put("id",d.getName()).put("title",p.optString("title","مشروع")));}return out;}
 static String text(JSONObject o,String key,int max,boolean empty)throws Exception{Object raw=o.opt(key);if(!(raw instanceof String))throw new IOException("بيانات نص غير صالحة");String s=(String)raw;if((!empty&&s.trim().isEmpty())||s.length()>max||s.matches("(?s).*[\\x00-\\x08\\x0b\\x0c\\x0e-\\x1f].*"))throw new IOException("اختصر نص المشهد أو العبارة");return s;}
 static double number(JSONObject o,String k,double a,double b)throws Exception{Object v=o.opt(k);if(!(v instanceof Number))throw new IOException("توقيت غير صالح");double n=((Number)v).doubleValue();if(!Double.isFinite(n)||n<a||n>b)throw new IOException("راجع حدود التوقيت");return n;}
 static JSONObject validate(JSONObject p,boolean exporting)throws Exception{
  if(p.toString().length()>700000||p.getInt("version")!=1||!p.getString("id").matches("[a-f0-9]{32}")||!Arrays.asList("paper","night","sand").contains(p.getString("theme"))||!Arrays.asList("9:16","16:9","1:1").contains(p.getString("aspect"))||!Arrays.asList("none","google","recording").contains(p.getString("voiceMode"))||!Arrays.asList("Charon","Kore","Algenib").contains(p.getString("voice"))||!Arrays.asList("documentary","warm").contains(p.optString("style","documentary")))throw new IOException("إعداد مشروع غير صالح");text(p,"title",80,false);if(p.has("product"))validateProduct(p.getJSONObject("product"));JSONArray scenes=p.getJSONArray("scenes");if(scenes.length()<1||scenes.length()>20)throw new IOException("اختر من مشهد إلى 20 مشهدًا");Set<String> ids=new HashSet<>();double total=0,previous=0;int chars=0;
  for(int i=0;i<scenes.length();i++){JSONObject s=scenes.getJSONObject(i);String sid=s.getString("id");if(!sid.matches("[a-f0-9]{12}")||!ids.add(sid)||!Arrays.asList("fade","rise","slide","zoom","pan","reveal").contains(s.getString("effect"))||!Arrays.asList("fade","slide").contains(s.getString("transition")))throw new IOException("إعداد حركة غير صالح");if(!Arrays.asList("none","steps","timeline","map","voice","ship","product").contains(s.optString("graphic","steps")))throw new IOException("رسم غير صالح");if(s.optString("graphic").equals("product")&&(!p.has("product")||!Arrays.asList("opening","components","benefits","process","claim","percent","closing").contains(s.optString("productStage"))||s.optString("productStage").equals("percent")&&!p.getJSONObject("product").getBoolean("confirmedPercent")))throw new IOException("إعداد مشهد المنتج غير صالح");text(s,"title",60,false);chars+=text(s,"narration",1000,false).length();total+=number(s,"seconds",1,120);String image=text(s,"image",80,true);if(!image.isEmpty()&&!image.matches("asset_[a-f0-9]{32}\\.jpg"))throw new IOException("صورة غير صالحة");if(s.has("imageSeconds"))number(s,"imageSeconds",.3,10);text(s,"imageAnchor",120,true);text(s,"imageQuery",180,true);text(s,"credit",700,true);
   if(exporting&&s.optString("graphic").equals("product")&&Arrays.asList("opening","closing").contains(s.optString("productStage"))&&image.isEmpty())throw new IOException("أرفق صورة المنتج قبل التصدير");double start=exporting?number(s,"start",previous,900):0,end=exporting?number(s,"end",start+.01,900):900;previous=end;if(exporting&&!image.isEmpty())number(s,"imageAt",start,end-.01);JSONArray hs=s.getJSONArray("highlights");if(hs.length()>12)throw new IOException("العبارات كثيرة داخل المشهد");for(int j=0;j<hs.length();j++){JSONObject h=hs.getJSONObject(j);String role=h.getString("role");if(!Arrays.asList("top","bottom").contains(role))throw new IOException("موضع العبارة غير صالح");text(h,"text",role.equals("top")?48:100,false);text(h,"anchor",120,false);number(h,"group",0,11);if(exporting){double a=number(h,"start",start,end-.01);number(h,"end",a+.01,end);}}
   if(exporting&&!p.getString("voiceMode").equals("none")&&(!p.optBoolean("ready")||s.optBoolean("needsReview")))throw new IOException("أكمل المزامنة وراجع العبارات غير المطابقة");
  }
  if(total>900||chars>10000)throw new IOException("اختصر المشروع إلى 15 دقيقة و10000 حرف");if(exporting&&Math.abs(number(p,"duration",.1,900)-previous)>.04)throw new IOException("مدة الفيديو غير متطابقة");return p;
 }
 static void validateProduct(JSONObject d)throws Exception{
  text(d,"name",60,false);text(d,"brand",60,false);text(d,"process",60,true);text(d,"claim",60,true);text(d,"cta",60,false);
  if(!Arrays.asList("grain","neutral").contains(d.getString("motif"))||!(d.opt("confirmedPercent") instanceof Boolean)||d.getBoolean("confirmedPercent")&&d.getString("claim").trim().isEmpty())throw new IOException("راجع معلومات مطابقة المنتج");
  for(String key:new String[]{"components","benefits"}){JSONArray a=d.getJSONArray(key);if(a.length()>3)throw new IOException("اكتب حتى ثلاث معلومات لكل مجموعة");Set<String> seen=new HashSet<>();for(int i=0;i<a.length();i++){String value=text(new JSONObject().put("v",a.get(i)),"v",48,false);if(value.matches("(?s).*[\\r\\n\\t].*")||!seen.add(value))throw new IOException("راجع معلومات المنتج المتكررة");}}
 }
 static String hash(File f)throws Exception{MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(f)){byte[] b=new byte[65536];int n;while((n=in.read(b))!=-1)digest.update(b,0,n);}return hex(digest.digest());}
 static String hash(String s)throws Exception{return hex(MessageDigest.getInstance("SHA-256").digest(s.getBytes(StandardCharsets.UTF_8)));}
 static String hex(byte[] bytes){StringBuilder s=new StringBuilder();for(byte b:bytes)s.append(String.format(Locale.ROOT,"%02x",b&255));return s.toString();}
 static String script(JSONObject p)throws Exception{StringBuilder s=new StringBuilder();JSONArray scenes=p.getJSONArray("scenes");for(int i=0;i<scenes.length();i++)s.append(scenes.getJSONObject(i).getString("narration")).append('\n');return s.toString();}
}
